class BoostingStrategy:
    """Stochastic Exact Newton Boosting."""

    def __init__(self, config):
        self.config = config
        self.task_type = config["task_type"]
        self.n_rounds = config["n_rounds"]
        self.learning_rate = config["learning_rate"]
        np.random.seed(config.get("seed", 42))

    def init_weights(self, n_samples):
        return np.ones(n_samples) / n_samples

    def compute_targets(self, y, current_predictions, sample_weights, round_idx):
        n_samples = len(y)
        # Bayesian Bootstrap weights
        noise = np.random.exponential(scale=1.0, size=n_samples)

        if self.task_type == "classification":
            p = 1.0 / (1.0 + np.exp(-np.clip(current_predictions, -15.0, 15.0)))
            g = y - p
            h = np.clip(p * (1.0 - p), 1e-4, 1.0)

            # Mutate sample_weights IN PLACE for the learner.fit call
            sample_weights[:] = h * noise + 1e-10

            # Exact Newton targets
            target = g / h
            return np.clip(target, -10.0, 10.0)
        else:
            g = y - current_predictions
            sample_weights[:] = noise + 1e-10
            return g

    def compute_learner_weight(self, learner, X, y, pseudo_targets,
                                sample_weights, round_idx):
        if self.task_type == "regression":
            preds = learner.predict(X)
            numerator = np.sum(pseudo_targets * preds)
            denominator = np.sum(preds ** 2) + 1.0
            return max(numerator / denominator, 0.01)
        else:
            return 1.0

    def update_weights(self, sample_weights, learner, X, y, pseudo_targets,
                       alpha, round_idx):
        return sample_weights

